service_b.sql:
SELECT DISTINCT CUS_NUM
FROM BI_DWH.PIO_TRANSACTIONS
WHERE TRA_DATE >= SYSDATE - :cs_b1;

SELECT CUS_NUM, AVG(TRA_AMT) AS AVG_TRA_AMT
FROM BI_DWH.PIO_TRANSACTIONS
GROUP BY CUS_NUM;

